import {
  allentriesParquets,
  parquetPath,
  runDuckDBQuery,
  toJSON,
} from "./db.js";
import { existsSync } from "fs";
import { fileURLToPath } from "url";
import path from "path";

// Observable dev server runs from observable/, so resolve from this script's location
// (observable/src/data/) up to the project root (../../../)
const projectRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../../..",
);

// ── Primary path: 3 pre-aggregated parquets (generated by `just update`) ────
// These are 3 small R2 requests, avoiding the 388-file fan-out that causes HTTP 429.
const statsParquet = parquetPath(
  "geonames",
  "allentries-stats.parquet",
  "observable",
);
const featureCodesParquet = parquetPath(
  "geonames",
  "allentries-feature-codes.parquet",
  "observable",
);
const capitalsParquet = parquetPath(
  "geonames",
  "allentries-capitals.parquet",
  "observable",
);

const [statsRows, featureRows, capitalsRows] = await Promise.all([
  runDuckDBQuery(
    "allentries-stats",
    `SELECT * FROM read_parquet(${JSON.stringify(statsParquet)})`,
  ),
  runDuckDBQuery(
    "allentries-feature-codes",
    `SELECT * FROM read_parquet(${JSON.stringify(featureCodesParquet)})`,
  ),
  runDuckDBQuery(
    "allentries-capitals",
    `SELECT * FROM read_parquet(${JSON.stringify(
      capitalsParquet,
    )}) ORDER BY population DESC NULLS LAST`,
  ),
]);

// If the pre-aggregated parquets exist and returned data, use them directly.
if (statsRows.length > 0 && capitalsRows.length > 0) {
  process.stdout.write(
    toJSON({
      stats: statsRows[0] ?? {},
      feature_codes: featureRows,
      capitals: capitalsRows,
    }),
  );
  process.exit(0);
}

// ── Fallback: full scan ──────────────────────────────────────────────────────
// Used during local dev before `just update` has run, or on old releases that
// predate the pre-aggregated parquets.

let fromExpr, ccExpr;

const rawFile = path.join(
  projectRoot,
  "downloaded",
  "geonames",
  "allCountries.txt",
);
const parquetResult = await allentriesParquets();

if (parquetResult && process.env.WDA_DATASET_PATH) {
  fromExpr = `read_parquet(${parquetResult.src})`;
  ccExpr = parquetResult.ccExpr;
} else if (existsSync(rawFile)) {
  const cols =
    `{'id':'INTEGER','name':'VARCHAR','asciiname':'VARCHAR','alternatenames':'VARCHAR',` +
    `'latitude':'DOUBLE','longitude':'DOUBLE','feature_class':'VARCHAR','feature_code':'VARCHAR',` +
    `'country_code':'VARCHAR','cc2':'VARCHAR','admin1_code':'VARCHAR','admin2_code':'VARCHAR',` +
    `'admin3_code':'VARCHAR','admin4_code':'VARCHAR','population':'BIGINT',` +
    `'elevation':'INTEGER','dem':'INTEGER','timezone':'VARCHAR','modification':'DATE'}`;
  fromExpr = `read_csv('${rawFile}', delim='\\t', header=false, quote='', columns=${cols})`;
  ccExpr = "country_code";
} else if (parquetResult) {
  fromExpr = `read_parquet(${parquetResult.src})`;
  ccExpr = parquetResult.ccExpr;
} else {
  process.stdout.write(toJSON({ stats: {}, feature_codes: [], capitals: [] }));
  process.exit(0);
}

const [fallbackStats, fallbackFeatures, fallbackCapitals] = await Promise.all([
  runDuckDBQuery(
    "allentries-stats",
    `SELECT
      COUNT(*)                                                      AS total_entries,
      COUNT(DISTINCT ${ccExpr})                                     AS total_countries,
      SUM(CASE WHEN feature_class = 'P' THEN 1 ELSE 0 END)         AS populated_places,
      SUM(CASE WHEN feature_class = 'A' THEN 1 ELSE 0 END)         AS admin_entries,
      SUM(CASE WHEN feature_class = 'P' AND population > 0
               THEN population ELSE 0 END)                         AS total_population
    FROM ${fromExpr}`,
  ),
  runDuckDBQuery(
    "allentries-feature-codes",
    `SELECT feature_code, COUNT(*) AS count
    FROM ${fromExpr}
    WHERE feature_class = 'P'
    GROUP BY feature_code
    ORDER BY count DESC
    LIMIT 15`,
  ),
  runDuckDBQuery(
    "allentries-capitals",
    `SELECT name, ${ccExpr} AS country_code, population, latitude, longitude
    FROM ${fromExpr}
    WHERE feature_code = 'PPLC'
      AND latitude IS NOT NULL AND longitude IS NOT NULL
    ORDER BY population DESC NULLS LAST`,
  ),
]);

process.stdout.write(
  toJSON({
    stats: fallbackStats[0] ?? {},
    feature_codes: fallbackFeatures,
    capitals: fallbackCapitals,
  }),
);
